TDEFINE_CLASS( AUnitPoolCue, 1, 0 );

// $Barnyard: FUNCTION 004d7d20
AUnitPoolCue::AUnitPoolCue()
    : m_vecDirection( TVector4::VEC_POSX )
    , m_vecCueBallPosition( TVector4::VEC_ZERO )
    , m_vecCuePosition( TVector4::VEC_ZERO )
    , m_fPower( 0.0f )
    , m_fMaxPower( 10.0f )
    , m_fCueLength( 2.0f )
    , m_eState( STATE_AIMING )
    , m_bPowerDecreasing( TFALSE )
{
}

// $Barnyard: FUNCTION 004d7de0
// $Barnyard: FUNCTION 004d8200
AUnitPoolCue::~AUnitPoolCue()
{
}

// $Barnyard: FUNCTION 004d8220
TBOOL AUnitPoolCue::Create( AUnitTransform* a_pTransform )
{
	if ( !AAnimatedUnit::Create( a_pTransform ) )
		return TFALSE;

	m_eFlags |= FLAGS_AI_ENABLED;
	m_eFlags |= FLAGS_THINK_ENABLED;

	GetAnimatableObject()->GetModelInstance()->SetUnlit();

	return TTRUE;
}

// $Barnyard: FUNCTION 004d82c0
void AUnitPoolCue::UpdateAI( TFLOAT a_fDeltaTime )
{
	switch ( m_eState )
	{
		case STATE_AIMING:
		{
			// Behind the cue ball...
			TVector4 vecOffset;
			vecOffset.Multiply( m_vecDirection, m_fCueLength );
			m_vecCuePosition.Set( m_vecCueBallPosition.x - vecOffset.x, m_vecCueBallPosition.y - vecOffset.y, m_vecCueBallPosition.z - vecOffset.z, m_vecCueBallPosition.w );

			// ...and pulled back by the power
			TVector4 vecMaxPullBack;
			vecMaxPullBack.Multiply( m_vecDirection, m_fCueLength * 0.25f );
			TVector4 vecPullBack;
			vecPullBack.Multiply( vecMaxPullBack, m_fPower / m_fMaxPower );

			m_vecCuePosition.x -= vecPullBack.x;
			m_vecCuePosition.y -= vecPullBack.y;
			m_vecCuePosition.z -= vecPullBack.z;

			GetAnimatableObject()->GetModelInstance()->SetTransform( m_vecCuePosition, m_vecDirection );

			// Fade in
			m_fTimer = TMath::Min( m_fTimer + a_fDeltaTime, 2.0f );
			GetAnimatableObject()->GetModelInstance()->SetOpacity( m_fTimer * 0.5f );
			break;
		}
		case STATE_SHOOTING:
		{
			m_fPullBackSpeed = TMath::Min( a_fDeltaTime * 2.2f + m_fPullBackSpeed, 0.4f );

			TVector4 vecVelocity;
			vecVelocity.Multiply( m_vecShotDirection, m_fPullBackSpeed );
			TVector4 vecMove;
			vecMove.Multiply( vecVelocity, a_fDeltaTime );

			m_vecCuePosition.x -= vecMove.x;
			m_vecCuePosition.y -= vecMove.y;
			m_vecCuePosition.z -= vecMove.z;

			GetAnimatableObject()->GetModelInstance()->SetTransform( m_vecCuePosition, m_vecShotDirection );

			m_fTimer -= a_fDeltaTime;

			if ( m_fTimer < 0.0f )
			{
				m_eState = STATE_SHOT;
				m_fTimer = 0.25f;
				m_fUnkF0 = 0.0f;
			}

			if ( m_fPullBackSpeed < 0.0f )
			{
				// Shake the cue while it moves forward
				TMatrix44 matTransform;
				GetAnimatableObject()->GetModelInstance()->GetLocalTransform( matTransform );

				TRandom& rRandom = ARandom::GetSingleton()->m_oRandom;

				TFLOAT fShake = m_fPullBackSpeed * 0.001f;
				matTransform.RotateX( rRandom.GetFloatMinMax( fShake, -fShake ) );
				fShake = m_fPullBackSpeed * 0.001f;
				matTransform.RotateY( rRandom.GetFloatMinMax( fShake, -fShake ) );
				fShake = m_fPullBackSpeed * 0.001f;
				matTransform.RotateZ( rRandom.GetFloatMinMax( fShake, -fShake ) );

				GetAnimatableObject()->GetModelInstance()->SetTransform( matTransform );
			}

			break;
		}
		case STATE_SHOT:
		{
			m_fTimer -= a_fDeltaTime;

			if ( m_fTimer < 0.0f )
			{
				m_eState         = STATE_FADING_OUT;
				m_fTimer         = 2.0f;
				m_fPullBackSpeed = 0.0f;
			}

			GetAnimatableObject()->GetModelInstance()->SetTransform( m_vecCuePosition, m_vecShotDirection );
			break;
		}
		case STATE_FADING_OUT:
		{
			m_fTimer = TMath::Max( m_fTimer - a_fDeltaTime, 0.0f );
			GetAnimatableObject()->GetModelInstance()->SetOpacity( m_fTimer * 0.5f );

			if ( m_fTimer <= 0.0f )
			{
				m_fTimer = 2.0f;
				m_eState = STATE_HIDDEN;
			}

			m_fPullBackSpeed = TMath::Min( a_fDeltaTime * 8.0f + m_fPullBackSpeed, 6.0f );

			TVector4 vecVelocity;
			vecVelocity.Multiply( m_vecShotDirection, m_fPullBackSpeed );
			TVector4 vecMove;
			vecMove.Multiply( vecVelocity, a_fDeltaTime );

			m_vecCuePosition.x -= vecMove.x;
			m_vecCuePosition.y -= vecMove.y;
			m_vecCuePosition.z -= vecMove.z;

			GetAnimatableObject()->GetModelInstance()->SetTransform( m_vecCuePosition, m_vecShotDirection );
			break;
		}
		case STATE_HIDDEN:
			GetAnimatableObject()->GetModelInstance()->SetTransform( m_vecCuePosition, m_vecShotDirection );
			break;
	}

	AVisibleUnit::UpdateAI( a_fDeltaTime );
}

// NOTE: a thunk to AVisibleUnit::Think (004d7ae0) shared by several classes in retail
TBOOL AUnitPoolCue::Think( TFLOAT a_fDeltaTime )
{
	return AVisibleUnit::Think( a_fDeltaTime );
}

// $Barnyard: FUNCTION 004d8100
void AUnitPoolCue::SetVisible( TBOOL a_bVisible )
{
	if ( !IsVisible() && a_bVisible )
	{
		// Fade in again when it's shown while aiming
		if ( m_eState == STATE_AIMING )
			m_fTimer = 0.0f;

		UpdateAI( 0.0f );
	}

	AAnimatedUnit::SetVisible( a_bVisible );
}

// $Barnyard: FUNCTION 004d7e00
void AUnitPoolCue::SetTarget( const TVector4& a_rcTarget )
{
	m_vecTarget = a_rcTarget;

	m_vecDirection.Set( m_vecTarget.x - m_vecCueBallPosition.x, m_vecTarget.y - m_vecCueBallPosition.y, m_vecTarget.z - m_vecCueBallPosition.z, m_vecTarget.w );
	m_vecDirection.Normalise();

	if ( TVector4::VEC_ZERO.IsEqual( m_vecDirection ) )
		m_vecDirection = TVector4::VEC_POSX;
}

// $Barnyard: FUNCTION 004d8070
void AUnitPoolCue::SetCueBallPosition( const TVector4& a_rcPosition )
{
	m_vecCueBallPosition = a_rcPosition;
}

// $Barnyard: FUNCTION 004d7eb0
TVector4 AUnitPoolCue::GetCuePosition()
{
	return m_vecCuePosition;
}

// $Barnyard: FUNCTION 004d7f10
void AUnitPoolCue::UpdatePowerOscillation( TFLOAT a_fDeltaTime )
{
	// The power changes faster the higher it is
	if ( m_bPowerDecreasing )
	{
		TFLOAT fPower = m_fPower - a_fDeltaTime;
		m_fPower      = fPower - fPower / m_fMaxPower * a_fDeltaTime;
	}
	else
	{
		TFLOAT fPower = a_fDeltaTime + m_fPower;
		m_fPower      = fPower / m_fMaxPower * a_fDeltaTime + fPower;
	}

	if ( m_fPower > m_fMaxPower )
	{
		m_fPower           = m_fMaxPower;
		m_bPowerDecreasing = !m_bPowerDecreasing;
	}

	if ( m_fPower < 0.01f )
	{
		m_fPower           = 0.01f;
		m_bPowerDecreasing = !m_bPowerDecreasing;
	}
}

// $Barnyard: FUNCTION 004d7fb0
void AUnitPoolCue::UpdatePullBack( TFLOAT a_fDeltaTime, TFLOAT a_fSpeedDeltaTime )
{
	TFLOAT fPower      = m_fPower - a_fDeltaTime;
	TFLOAT fOneOverMax = 1.0f / m_fMaxPower;
	fPower             = fPower - fOneOverMax * fPower * a_fDeltaTime;
	m_fPower           = fPower;

	TFLOAT fPullBack = fPower * fOneOverMax * ( m_fCueLength * 0.25f );
	m_fPullBackSpeed = ( fPullBack - m_fPullBack ) / a_fSpeedDeltaTime;
	m_fPullBack      = fPullBack;
}

// $Barnyard: FUNCTION 004d8010
TFLOAT AUnitPoolCue::ResetPower()
{
	TFLOAT fPower = m_fPower;
	m_fPower      = 0.0f;
	m_eState      = STATE_AIMING;

	return fPower;
}

// $Barnyard: FUNCTION 004d8030
TVector4 AUnitPoolCue::GetShotVelocity()
{
	TVector4 vecVelocity;
	vecVelocity.Multiply( m_vecDirection, m_fPower );

	return vecVelocity;
}

// $Barnyard: FUNCTION 004d80a0
void AUnitPoolCue::Shoot()
{
	m_fPullBackSpeed *= 0.99f;
	m_vecShotDirection = m_vecDirection;
	m_eState           = STATE_SHOOTING;
	m_fTimer           = 0.06f;
	m_bPowerDecreasing = TFALSE;
}
